function mirrorCuts(text) {
  const pal = (s) => s === [...s].reverse().join('');
  const go = (start) => {
    if (pal(text.slice(start))) return 0;
    let best = Infinity;
    for (let end = start + 1; end < text.length; end++)
      if (pal(text.slice(start, end))) best = Math.min(best, 1 + go(end));
    return best;
  };
  return go(0);
}

function mirrorCuts(text) {
  const n = text.length;
  const cuts = Array.from({ length: n + 1 }, (_, i) => i - 1);
  for (let center = 0; center < n; center++) {
    for (const [startL, startR] of [[center, center], [center, center + 1]]) {
      let l = startL, r = startR;
      while (l >= 0 && r < n && text[l] === text[r]) {
        cuts[r + 1] = Math.min(cuts[r + 1], cuts[l] + 1);
        l--;
        r++;
      }
    }
  }
  return cuts[n];
}
